const MAX_PARTICLE_COUNT = 322;
const MAX_TRAIL_COUNT = 11;

let colorScheme = ["#E69F66", "#DF843A", "#D8690F", "#B1560D", "#8A430A"];
let shaded = true;
let theShader;
let shaderTexture;
let trail = [];
let particles = [];

let cachedTrailPoint = [0, 0];
let cachedParticleOffset = [0, 0];

// Intermittent spawn via cooldown
let spawnCooldown = 0;
let SPAWN_INTERVAL = 40; // frames between each single spawn

function preload() {
  theShader = createShader(vertShader, fragShader);
}

function setup() {
  pixelDensity(1);
  let canvasSize = max(windowWidth, windowHeight);
  let canvas = createCanvas(canvasSize, canvasSize, WEBGL);
  canvas.canvas.oncontextmenu = () => false;
  noCursor();

  shaderTexture = createGraphics(width, height, WEBGL);
  shaderTexture.noStroke();
}

function draw() {
  background(0);
  noStroke();

  // Update cached random position less often
  if (frameCount % 21 === 0) {
    cachedTrailPoint = [
      Math.floor(Math.random() * width),
      Math.floor(Math.random() * height)
    ];
    cachedParticleOffset = [
      random(-20, 20),
      random(-20, 20)
    ];
  }

  // Trail logic
  trail.push([...cachedTrailPoint]);

  let removeCount = (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === CENTER) ? 2 : 1;
  for (let i = 0; i < removeCount && trail.length > 0; i++) {
    if (trail.length > MAX_TRAIL_COUNT || ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
      trail.shift();
    }
  }

  // === Intermittent Particle Trigger ===
  if (spawnCooldown <= 0 && particles.length < MAX_PARTICLE_COUNT) {
    let movement = dist((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), (window.simulatedPMouseX !== undefined ? window.simulatedPMouseX : (typeof sub_bass_prev !== 'undefined' ? map(sub_bass_prev, 0, 1, width*0.1, width*0.9) : (typeof window.simulatedMouseX !== 'undefined' ? window.simulatedMouseX - 12 : pmouseX))), (window.simulatedPMouseY !== undefined ? window.simulatedPMouseY : (typeof percussive_prev !== 'undefined' ? map(percussive_prev, 0, 1, height, 0) : (typeof window.simulatedMouseY !== 'undefined' ? window.simulatedMouseY - 12 : pmouseY))));
    if (movement > 10) {
      let p = new Particle(
        random(-20, 20),
        random(-20, 20),
        random(-1, 1),
        random(-1, 1)
      );
      particles.push(p);
      spawnCooldown = SPAWN_INTERVAL;
    }
  } else {
    spawnCooldown--;
  }

  translate(-width / 2, -height / 2);

  // Update particles
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].move();
    if (particles[i].vel.mag() < 0.1) {
      particles.splice(i, 1);
    }
  }

  if (shaded) {
    shaderTexture.shader(theShader);
    let data = serializeSketch();

    theShader.setUniform("resolution", [width, height]);
    theShader.setUniform("trailCount", trail.length);
    theShader.setUniform("trail", data.trails);
    theShader.setUniform("particleCount", particles.length);
    theShader.setUniform("particles", data.particles);
    theShader.setUniform("colors", data.colors);

    shaderTexture.rect(0, 0, width, height);
    texture(shaderTexture);
    rect(0, 0, width, height);
  } else {
    stroke(255, 200, 0);
    for (let p of particles) {
      point(p.pos.x, p.pos.y);
    }

    stroke(0, 255, 255);
    for (let t of trail) {
      point(t[0], t[1]);
    }

    fill(spawnCooldown === 0 ? 'green' : 'red');
    noStroke();
    ellipse(width - 20, height - 20, 10);
  }
}
