function mousePressed() {
  if (mouseButton === RIGHT) {
    shaded = !shaded;
  }
}

function mouseReleased() {
  if (mouseButton === LEFT) {
    burstParticles((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 12);
  }
}
*/
function burstParticles(x, y, count) {
  for (let i = 0; i < count; i++) {
    if (particles.length < MAX_PARTICLE_COUNT) {
      particles.push(new Particle(
        x + random(-5, 5),
        y + random(-5, 5),
        random(-2, 2),
        random(-2, 2)
      ));
    }
  }
}

function serializeSketch() {
  var data = { trails: [], particles: [], colors: [] };

  for (let t of trail) {
    data.trails.push(
      map(t[0], 0, width, 0.0, 1.0),
      map(t[1], 0, height, 1.0, 0.0)
    );
  }

  for (let p of particles) {
    data.particles.push(
      map(p.pos.x, 0, width, 0.0, 1.0),
      map(p.pos.y, 0, height, 1.0, 0.0),
      p.mass * p.vel.mag() / 100
    );

    let c = color(colorScheme[p.colorIndex]);
    data.colors.push(red(c) / 255.0, green(c) / 255.0, blue(c) / 255.0);
  }

  return data;
}


// === Tab: particle ===

class Particle {
  constructor(x, y, dx, dy) {
    this.pos = createVector(x, y);
    this.vel = createVector(dx, dy).mult(random(0.5, 2.5));
    this.acc = createVector(0, 0);
    this.mass = random(0.5, 2);
    this.colorIndex = floor(random(colorScheme.length));
  }

  move() {
    this.acc.add(p5.Vector.random2D().mult(0.02));
    this.vel.add(this.acc);
    this.vel.limit(3);
    this.pos.add(this.vel);
    this.acc.mult(0);
  }
}


// === Tab: shader ===
let vertShader = `
	precision highp float;

	attribute vec3 aPosition;

	void main() {
		vec4 positionVec4 = vec4(aPosition, 1.0);
		positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
		gl_Position = positionVec4;
	}
`;

let fragShader = `
	precision highp float;

	uniform vec2 resolution;
	uniform int trailCount;
	uniform vec2 trail[${MAX_TRAIL_COUNT}];
	uniform int particleCount;
	uniform vec3 particles[${MAX_PARTICLE_COUNT}];
	uniform vec3 colors[${MAX_PARTICLE_COUNT}];

	void main() {
			vec2 st = gl_FragCoord.xy / resolution.xy;  // Warning! This is causing non-uniform scaling.

			float r = 0.0;
			float g = 0.0;
			float b = 0.0;

			for (int i = 0; i < ${MAX_TRAIL_COUNT}; i++) {
				if (i < trailCount) {
					vec2 trailPos = trail[i];
					float value = float(i) / distance(st, trailPos.xy) * 0.00015;  // Multiplier may need to be adjusted if max trail count is tweaked.
					g += value * 0.5;
					b += value;
				}
			}

			float mult = 0.00005;

			for (int i = 0; i < ${MAX_PARTICLE_COUNT}; i++) {
				if (i < particleCount) {
					vec3 particle = particles[i];
					vec2 pos = particle.xy;
					float mass = particle.z;
					vec3 color = colors[i];

					r += color.r / distance(st, pos) * mult * mass;
					g += color.g / distance(st, pos) * mult * mass;
					b += color.b / distance(st, pos) * mult * mass;
				}
			}

			gl_FragColor = vec4(r, g, b, 1.0);
	}
`;

